export interface ScreeningTransaction {
  carbonFootprint?: {
    co2Emissions?: number;
    screeningCo2Emissions?: number;
    complianceFlags?: string[] | Record<string, boolean>;
  };
}

const GAP_LABELS: Record<string, string> = {
  spend_proxy_excluded_from_inventory: 'Rupee-only rows are screening, not inventory. Add kWh, litres, kg, or tonne-km.',
  cat6_requires_room_nights: 'Hotel rows need room-nights.',
  cat6_requires_passenger_km: 'Business travel needs passenger-km, or room-nights for a hotel.',
  cat7_requires_commute_km: 'Employee commuting needs passenger-km.',
  cat7_wfh_requires_hours_or_kwh: 'Work-from-home needs hours or kWh.',
  cat4_requires_tonne_km: 'Inbound freight needs tonne-km or a fuel quantity.',
  cat9_requires_tonne_km: 'Outbound freight needs tonne-km or a fuel quantity.',
  cat8_requires_energy_data: 'Upstream leased assets need energy data.',
  cat13_requires_energy_data: 'Downstream leased assets need energy data.',
  cat10_requires_processing_data: 'Processing needs a processing kilogram figure.',
  unspecified_fuel_type: 'Name the fuel. Unnamed fuel stays at zero.',
  cat3_fuel_upstream_not_applied: 'Fuel upstream is not applied. No India well-to-tank factor is in the pack.',
  cat6_hotel_factor_not_india: 'Hotel nights stay at zero. No India-cited hotel factor is in the pack.',
  flight_factor_not_india: 'Flight kilometres stay at zero. No India-cited flight factor is in the pack.',
  road_passenger_factor_not_india: 'Car and taxi kilometres stay at zero. No India-cited passenger-km factor is in the pack.',
  cat7_wfh_hour_factor_not_india: 'Home-working hours stay at zero. Enter kWh to use the CEA grid factor.',
  factor_not_assurance_grade: 'An activity factor is outside the cited IPCC, CEA, CPCB, or BEE set.'
};

const flagList = (flags?: string[] | Record<string, boolean>): string[] => {
  if (Array.isArray(flags)) return flags.map((flag) => String(flag));
  if (flags && typeof flags === 'object') {
    return Object.entries(flags).filter(([, on]) => Boolean(on)).map(([flag]) => flag);
  }
  return [];
};

export const activityGapLabel = (code: string): string => GAP_LABELS[code] || code;

export const summarizeInventoryAndScreening = (transactions: ScreeningTransaction[] = []) => {
  let inventoryKg = 0;
  let screeningKg = 0;
  const gapCodes = new Set<string>();
  transactions.forEach((transaction) => {
    const footprint = transaction.carbonFootprint || {};
    inventoryKg += Number(footprint.co2Emissions) || 0;
    screeningKg += Number(footprint.screeningCo2Emissions) || 0;
    flagList(footprint.complianceFlags).forEach((flag) => {
      if (GAP_LABELS[flag]) gapCodes.add(flag);
    });
  });
  return {
    inventoryKg,
    screeningKg,
    gapCodes: Array.from(gapCodes),
    gapLabels: Array.from(gapCodes).map(activityGapLabel)
  };
};
